      { text: "Refrain from anger and turn from wrath; do not fret—it leads only to evil.", reference: "Psalm 37:8", translation: "NIV", theme: "anger" },
      { text: "A person's wisdom yields patience; it is to one's glory to overlook an offense.", reference: "Proverbs 19:11", translation: "NIV", theme: "anger" },
      { text: "Get rid of all bitterness, rage and anger, brawling and slander, along with every form of malice.", reference: "Ephesians 4:31", translation: "NIV", theme: "anger" },
      { text: "Whoever is patient has great understanding, but one who is quick-tempered displays folly.", reference: "Proverbs 14:29", translation: "NIV", theme: "anger" },
      { text: "The Lord is compassionate and gracious, slow to anger, abounding in love.", reference: "Psalm 103:8", translation: "NIV", theme: "anger" },
      { text: "But now you must also rid yourselves of all such things as these: anger, rage, malice, slander, and filthy language.", reference: "Colossians 3:8", translation: "NIV", theme: "anger" },
      { text: "Do not be quickly provoked in your spirit, for anger resides in the lap of fools.", reference: "Ecclesiastes 7:9", translation: "NIV", theme: "anger" },
      { text: "for the anger of man doesn’t produce the righteousness of God.", reference: "James 1:20", translation: "WEB", theme: "anger" },
      { text: "One who is slow to anger is better than the mighty; one who rules his spirit, than he who takes a city.", reference: "Proverbs 16:32", translation: "WEB", theme: "anger" },
      { text: "A wrathful man stirs up contention, but one who is slow to anger appeases strife.", reference: "Proverbs 15:18", translation: "WEB", theme: "anger" },
      { text: "But I tell you, that everyone who is angry with his brother without a cause will be in danger of the judgment; and whoever says to his brother, ‘Raca!’ will be in danger of the council; and whoever says, ‘You fool!’ will be in danger of the fire of Gehenna.", reference: "Matthew 5:22", translation: "WEB", theme: "anger" },
      { text: "Yahweh is merciful and gracious, slow to anger, and abundant in loving kindness.", reference: "Psalms 103:8", translation: "WEB", theme: "anger" },
      { text: "He who is quick to become angry will commit folly, and a crafty man is hated.", reference: "Proverbs 14:17", translation: "WEB", theme: "anger" },
      { text: "I wish that those who disturb you would cut themselves off.", reference: "Galatians 5:12", translation: "WEB", theme: "anger" },
      { text: "“‘You shall not hate your brother in your heart. You shall surely rebuke your neighbor, and not bear sin because of him. “‘You shall not take vengeance, nor bear any grudge against the children of your people; but you shall love your neighbor as yourself. I am Yahweh.", reference: "Leviticus 19:17-18", translation: "WEB", theme: "anger" },
      { text: "Don’t seek revenge yourselves, beloved, but give place to God’s wrath. For it is written, “Vengeance belongs to me; I will repay, says the Lord.”", reference: "Romans 12:19", translation: "WEB", theme: "anger" },
      { text: "Let all bitterness, wrath, anger, outcry, and slander, be put away from you, with all malice. And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.", reference: "Ephesians 4:31-32", translation: "WEB", theme: "anger" },
      { text: "An angry man stirs up strife, and a wrathful man abounds in sin.", reference: "Proverbs 29:22", translation: "WEB", theme: "anger" },
      { text: "Now the deeds of the flesh are obvious, which are: adultery, sexual immorality, uncleanness, lustfulness, idolatry, sorcery, hatred, strife, jealousies, outbursts of anger, rivalries, divisions, heresies, envy, murders, drunkenness, orgies, and things like these; of which I forewarn you, even as I also forewarned you, that those who practice such things will not inherit God’s Kingdom.", reference: "Galatians 5:19-21", translation: "WEB", theme: "anger" },
      { text: "It is an honor for a man to keep aloof from strife; but every fool will be quarreling.", reference: "Proverbs 20:3", translation: "WEB", theme: "anger" },
      { text: "Stand in awe, and don’t sin. Search your own heart on your bed, and be still. Selah.", reference: "Psalms 4:4", translation: "WEB", theme: "anger" },
      { text: "Where do wars and fightings among you come from? Don’t they come from your pleasures that war in your members? You lust, and don’t have. You murder and covet, and can’t obtain. You fight and make war. You don’t have, because you don’t ask.", reference: "James 4:1-2", translation: "WEB", theme: "anger" },
      { text: "Don’t befriend a hot-tempered man, and don’t associate with one who harbors anger: lest you learn his ways, and ensnare your soul.", reference: "Proverbs 22:24-25", translation: "WEB", theme: "anger" },
      { text: "Pride only breeds quarrels, but with ones who take advice is wisdom.", reference: "Proverbs 13:10", translation: "WEB", theme: "anger" },
      { text: "For the overseer must be blameless, as God’s steward; not self-pleasing, not easily angered, not given to wine, not violent, not greedy for dishonest gain;", reference: "Titus 1:7", translation: "WEB", theme: "anger" },
      { text: "Therefore Yahweh was very angry with Israel, and removed them out of his sight. There was none left but the tribe of Judah only.", reference: "2 Kings 17:18", translation: "WEB", theme: "anger" }
