      { text: "Pure religion and undefiled before our God and Father is this: to visit the fatherless and widows in their affliction, and to keep oneself unstained by the world.", reference: "James 1:27", translation: "WEB", theme: "widows" },
      { text: "Yahweh will uproot the house of the proud, but he will keep the widow’s borders intact.", reference: "Proverbs 15:25", translation: "WEB", theme: "widows" },
      { text: "Soon afterwards, he went to a city called Nain. Many of his disciples, along with a great multitude, went with him. Now when he came near to the gate of the city, behold, one who was dead was carried out, the only son of his mother, and she was a widow. Many people of the city were with her. When the Lord saw her, he had compassion on her, and said to her, “Don’t cry.” He came near and touched the coffin, and the bearers stood still. He said, “Young man, I tell you, arise!” He who was dead sat up, and began to speak. And he gave him to his mother.", reference: "Luke 7:11-15", translation: "WEB", theme: "widows" },
      { text: "Jesus sat down opposite the treasury, and saw how the multitude cast money into the treasury. Many who were rich cast in much. A poor widow came, and she cast in two small brass coins, which equal a quadrans coin. He called his disciples to himself, and said to them, “Most certainly I tell you, this poor widow gave more than all those who are giving into the treasury, for they all gave out of their abundance, but she, out of her poverty, gave all that she had to live on.”", reference: "Mark 12:41-44", translation: "WEB", theme: "widows" },
      { text: "and she had been a widow for about eighty-four years), who didn’t depart from the temple, worshiping with fastings and petitions night and day.", reference: "Luke 2:37", translation: "WEB", theme: "widows" },
      { text: "So then if, while the husband lives, she is joined to another man, she would be called an adulteress. But if the husband dies, she is free from the law, so that she is no adulteress, though she is joined to another man.", reference: "Romans 7:3", translation: "WEB", theme: "widows" },
      { text: "to deprive the needy from justice, and to rob the poor among my people of their rights, that widows may be their plunder, and that they may make the fatherless their prey!", reference: "Isaiah 10:2", translation: "WEB", theme: "widows" },
      { text: "You have sent widows away empty, and the arms of the fatherless have been broken.", reference: "Job 22:9", translation: "WEB", theme: "widows" },
      { text: "For if you thoroughly amend your ways and your doings, if you thoroughly execute justice between a man and his neighbor; if you don’t oppress the foreigner, the fatherless, and the widow, and don’t shed innocent blood in this place, and don’t walk after other gods to your own hurt; then I will cause you to dwell in this place, in the land that I gave to your fathers, from of old even forever more.", reference: "Jeremiah 7:5-7", translation: "WEB", theme: "widows" },
      { text: "the blessing of him who was ready to perish came on me, and I caused the widow’s heart to sing for joy.", reference: "Job 29:13", translation: "WEB", theme: "widows" },
      { text: "But I say to the unmarried and to widows, it is good for them if they remain even as I am.", reference: "1 Corinthians 7:8", translation: "WEB", theme: "widows" },
      { text: "“Thus has Yahweh of Armies spoken, saying, ‘Execute true judgment, and show kindness and compassion every man to his brother. Don’t oppress the widow, nor the fatherless, the foreigner, nor the poor; and let none of you devise evil against his brother in your heart.’", reference: "Zechariah 7:9-10", translation: "WEB", theme: "widows" },
      { text: "Sing to God! Sing praises to his name! Extol him who rides on the clouds: to Yah, his name! Rejoice before him! A father of the fatherless, and a defender of the widows, is God in his holy habitation.", reference: "Psalms 68:4-5", translation: "WEB", theme: "widows" },
      { text: "if you don’t oppress the foreigner, the fatherless, and the widow, and don’t shed innocent blood in this place, and don’t walk after other gods to your own hurt;", reference: "Jeremiah 7:6", translation: "WEB", theme: "widows" },
      { text: "Open your mouth, judge righteously, and serve justice to the poor and needy.”", reference: "Proverbs 31:9", translation: "WEB", theme: "widows" }
